import { Router } from "express";
import {
  createUser,
  getAllUsers,
  findUserById,
  findUserByEmail,
  updateUser,
  deleteUser,
  updateLoginTime,
  updateLogoutTime,
} from "../controllers/UserController";
import { authMiddleware } from "../MiddleWare/authMiddleware";
import { requireRole } from "../MiddleWare/roleMiddleware";

const router = Router();

router.post("/", createUser);                                          // signup — public
router.get("/", authMiddleware, requireRole("admin"), getAllUsers);    // admin only — full user list
router.get("/:id", authMiddleware, findUserById);                      // any logged-in user
router.get("/email/:email", authMiddleware, requireRole("admin"), findUserByEmail);
router.put("/:id", authMiddleware, updateUser);                        // logged-in user (ideally check self/admin inside controller)
router.delete("/:id", authMiddleware, requireRole("admin"), deleteUser);
router.put("/:id/login", updateLoginTime);                             // called during login flow, no token yet
router.put("/:id/logout", authMiddleware, updateLogoutTime);

export default router;